import { readdir, readFile, writeFile } from "node:fs/promises";
import { createHash } from "node:crypto";
import { fileURLToPath } from "node:url";
import { resolve } from "node:path";

export async function buildSchemaSql() {
  const directory = new URL("../db/migrations/", import.meta.url);
  const statements = [
    "-- Generated by pnpm run db:export-schema. Do not edit manually.",
    "-- Install into a NEW, EMPTY PostgreSQL database only.",
    "-- For an existing installation use pnpm run db:migrate instead.",
    "BEGIN;",
    "SELECT pg_advisory_xact_lock(527113204);",
    "CREATE TABLE schema_migrations (name text PRIMARY KEY, checksum text NOT NULL, applied_at timestamptz NOT NULL DEFAULT now());",
  ];
  for (const name of (await readdir(directory))
    .filter((name) => name.endsWith(".sql"))
    .sort()) {
    const sql = await readFile(new URL(name, directory), "utf8");
    const checksum = createHash("sha256").update(sql).digest("hex");
    statements.push(
      `\n-- Migration: ${name}`,
      sql.trimEnd(),
      `INSERT INTO schema_migrations(name, checksum) VALUES ('${name.replaceAll("'", "''")}', '${checksum}');`,
    );
  }
  statements.push("COMMIT;", "");
  return statements.join("\n");
}

if (
  process.argv[1] &&
  resolve(process.argv[1]) === fileURLToPath(import.meta.url)
) {
  await writeFile(
    new URL("../db/schema.sql", import.meta.url),
    await buildSchemaSql(),
  );
  console.log("Exported db/schema.sql from versioned migrations.");
}
